pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address caller) internal {
        caller = address(this);
        try c.owned() {} catch { return; }
        assertTrue(c.owner() == caller);
    }

    function testFuzz_run(address caller) public {
        _run(caller);
    }

    receive() external payable {}
}
